        case 21: return "i64Load"
        case 22: return "f32Load"
        case 23: return "f64Load"
        case 24: return "i32Load8S"
        case 25: return "i32Load8U"
        case 26: return "i32Load16S"
        case 27: return "i32Load16U"
        case 28: return "i64Load8S"
